#include<iostream>
#include<string>
#include<vector>
#include<queue>
using namespace std;
int dx[] = {-1,0,1,0};
int dy[] = {0,1,0,-1};
int N;
vector<string> mat;
vector<string> mat2;
vector<vector<int> >v1;
void flood(int x,int y,vector<vector<int> >& v)
{
	queue<int> q;
	q.push(x*N+y);
	while(!q.empty())
	{
		int cx = q.front()/N;
		int cy = q.front()%N;
		q.pop();
		for(int d=0;d<4;d++)
		{
			int nx = cx+dx[d];
			int ny = cy+dy[d];
			if(nx<0 || nx>=N || ny<0 || ny>=N || v[nx][ny]!=-1 || mat[nx][ny]=='Y')
				continue;
			if(isdigit(mat2[nx][ny]) && mat2[nx][ny]!='0' && (v[cx][cy]+1<= v1[nx][ny]||v1[nx][ny]==-1))
			{
				v[nx][ny] = v[cx][cy]+1;
				if(v[nx][ny]!=v1[nx][ny])
					q.push(nx*N+ny);
			}
			else if(v1[nx][ny]==-1 || v1[nx][ny]> v[cx][cy]+1)
			{
				v[nx][ny] = v[cx][cy]+1;
				q.push(nx*N+ny);
			}
		}
	}
}
void init(int x,int y,vector<vector<int> >& v)
{
	v.clear();
	v.resize(N,vector<int>(N,-1));
	v[x][y]=0;
	flood(x,y,v);
}
void buildGraph(vector<string> m,vector< vector<vector<int> > >& v)
{
	v.resize(N*N);
	int i,j;
	for(i=0;i<N;i++)
		for(j=0;j<N;j++)
			if(isdigit(m[i][j]) && m[i][j]!='0')
				init(i,j,v[i*N+j]);
}

const int INF=1000000000;
int maxN=110;

struct node {
	int from, to, cost, flow;
	node(int f, int t, int c, int fl): from(f), to(t), cost(c), flow(fl) {}
};

struct MinCostFlow {
	int totalNodes;
	vector<int> cost, flow, parent;
	vector<node> edges;
	int totalCost, totalFlow;
	pair<int,int> getResults() { return make_pair(totalCost, totalFlow); }
	int getFlow() { return totalFlow; }
	int getCost() { return totalCost; }
	void reset(int n) {
		maxN=totalNodes=n;
		cost.assign(n,INF);
		flow.assign(n,0);
		parent.resize(n);
	}
	void addEdge(int u, int v, int c, int f) {
		edges.emplace_back(u,v,c,f);
		edges.emplace_back(v,u,-c,0);
	}
	void findPath(int s, int t) {
		reset(maxN);
		flow[s]=INT_MAX;
		cost[s]=0;
		bool changed;
		for(int i=0; i<Nodes; i++) {
			changed=false;
			for(auto &e:edges) {
				if(e.flow>0 && cost[e.to]>cost[e.from]+e.cost) {
					cost[e.to]=cost[e.from]+e.cost;
					flow[e.to]=min(flow[e.from], e.flow);
					parent[e.to]=&e - &edges[0];
					changed=true;
				}
			}
			if(!changed) break;
		}
	}
	void run(int s, int t) {
		if(s==t){ totalCost=0; totalFlow=INT_MAX; }
		totalCost=0; totalFlow=0;
		while(true) {
			findPath(s,t);
			if(flow[t]==0) break;
			for(int cur=t; cur!=s; cur=edges[parent[cur]].from) {
				int idx=parent[cur];
				edges[idx].flow -= flow[t];
				edges[idx^1].flow += flow[t];
				totalCost += edges[idx].cost * flow[t];
			}
			totalFlow += flow[t];
		}
	}
};
#define IN_NODE(x) (2*(x))
#define OUT_NODE(x) (2*(x)+1)
MinCostFlow mcf;
void connect(int i,int j,int x,int y)
{
	int n1 = i*N+j;
	int n2 = x*N+y + N*N;
	mcf.addEdge(OUT_NODE(n1), IN_NODE(n2), 0, 1000000);
}
int main()
{
#ifndef ONLINE_JUDGE
	freopen("in.txt","rt",stdin);
#endif
	int n,t;
	cin>>n>>t;
	vector<string> a,b;
	N=n;
	a.resize(n);
	b.resize(n);
	int si,sj;
	for(int i=0;i<n;i++)
	{
		cin>>a[i];
		for(int j=0;j<n;j++)
			if(a[i][j]=='Z')
			{
				si=i; sj=j;
			}
	}
	mat=a;
	for(int i=0;i<n;i++)
		cin>>b[i];
	mat2=b;
	vector<vector<int> >v;
	vector<vector<vector<int> > >vv;
	v1=vector<vector<int> >(N,vector<int>(N,1000000));
	init(si,sj,v);
	v1=v;
	buildGraph(a,vv);
	mcf.reset(4*N*N+2);
	int src=4*N*N;
	for(int i=0;i<N*N;i++)
	{
		mcf.addEdge(src,IN_NODE(i),0,1000000);
		mcf.addEdge(OUT_NODE(N*N+i),src+1,0,1000000);
	}
	for(int x=0;x<N;x++)
		for(int y=0;y<N;y++)
		{
			if(isdigit(a[x][y]))
			{
				int k=x*N+y;
				mcf.addEdge(IN_NODE(k),OUT_NODE(k),0,a[x][y]-'0');
			}
			if(isdigit(b[x][y]))
			{
				int k=x*N+y+N*N;
				mcf.addEdge(IN_NODE(k),OUT_NODE(k),0,b[x][y]-'0');
			}
		}
	for(int i=0;i<N;i++)
		for(int j=0;j<N;j++)
			if(isdigit(b[i][j]) && b[i][j]!='0')
			{
				for(int k=0;k<vv.size();k++)
				{
					if(vv[k].size())
					{
						int x=k/N;
						int y=k%N;
						if(vv[k][i][j]==-1 || vv[k][i][j]>t) continue;
						connect(x,y,i,j);
					}
				}
			}
	mcf.run(src, src+1);
	cout<<mcf.getFlow()<<endl;
	return 0;
}
